def into_spaces(apps, schema_editor):
    """Workspace apps go to a Company space; people's own apps to their personal space."""
    App = apps.get_model('core', 'App')
    Space = apps.get_model('core', 'Space')
    if App.objects.filter(owner__isnull=True, space__isnull=True).exists():
        company, _ = Space.objects.get_or_create(key='CO', defaults={
            'name': 'Company', 'kind': 'company', 'visibility': 'internal', 'icon': '🏢', 'color': '#2e7d5b', 'position': 0,
            'description': 'The apps the whole company works with.'})
        App.objects.filter(owner__isnull=True, space__isnull=True).update(space=company)
    for app in App.objects.filter(owner__isnull=False, space__isnull=True).select_related('owner'):
        user = app.owner
        space = Space.objects.filter(owner=user).first()
        if space is None:
            key, n = f'~{user.username}'[:20], 2
            while Space.objects.filter(key=key).exists():
                key, n = f'~{user.username}'[:17] + str(n), n + 1
            space = Space.objects.create(name=(f'{user.first_name} {user.last_name}'.strip() or user.username),
                                         key=key, kind='personal', visibility='private', owner=user, icon='🏠')
        app.space = space
        app.save(update_fields=['space'])


